CREATE MATERIALIZED VIEW non_leaf_1152 AS
SELECT n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum, mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, it1.id AS it1_id, it1.info AS it1_info, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role
FROM name AS n, movie_info AS mi1, info_type AS it1, cast_info AS ci, role_type AS rt
WHERE n.id = ci.person_id AND n.name ~~* '%gen%' AND mi1.movie_id = ci.movie_id AND mi1.info_type_id = it1.id AND mi1.info IN ('Action', 'Adult', 'Adventure', 'Animation', 'Canada', 'Comedy', 'Crime', 'Denmark', 'Documentary', 'Drama', 'Fantasy', 'Germany', 'Music', 'Short', 'Thriller', 'USA', 'West Germany') AND it1.id IN ('3', '8}'::integ') AND ci.role_id = rt.id AND rt.role IN ('costume designer', 'director', 'miscellaneous crew');